<?php declare(strict_types=1); ?>
<?php if($errors): ?><div class="alert"><?= kd_e(implode(' ',$errors)) ?></div><?php endif; ?><?php if($success): ?><div class="settings-success"><?= kd_e($success) ?></div><?php endif; ?>
<div class="marketplace-grid"><section class="panel customer-form-panel"><h3>PayTR iFrame ödeme bağlantısı</h3><p class="muted">Mağaza bilgileri şifrelenerek sunucuda saklanır. Callback adresini PayTR mağaza paneline tanımlayın: <strong>/payment_callback.php</strong></p><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="paytr"><label>Mağaza numarası<input name="merchant_id" value="<?= kd_e($cfg['merchant_id']??'') ?>" required></label><label>Mağaza anahtarı<input type="password" name="merchant_key" autocomplete="new-password" placeholder="Değiştirmeyecekseniz boş bırakın"></label><label>Mağaza salt<input type="password" name="merchant_salt" autocomplete="new-password" placeholder="Değiştirmeyecekseniz boş bırakın"></label><label><input type="checkbox" name="enabled" value="1" <?= !empty($cfg['enabled'])?'checked':'' ?>> PayTR ödemelerini etkinleştir</label><label><input type="checkbox" name="test_mode" value="1" <?= !empty($cfg['test_mode'])?'checked':'' ?>> Test modu</label><button class="btn primary">PayTR ayarlarını kaydet</button></form></section>
<section class="panel customer-form-panel"><h3>Banka havalesi / kapıda ödeme</h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="manual"><label><input type="checkbox" name="bank_transfer_enabled" value="1" <?= ($settings['bank_transfer_enabled']??'1')==='1'?'checked':'' ?>> Banka havalesini etkinleştir</label><label><input type="checkbox" name="cash_on_delivery_enabled" value="1" <?= ($settings['cash_on_delivery_enabled']??'1')==='1'?'checked':'' ?>> Kapıda ödemeyi etkinleştir</label><label>Havale talimatı<textarea name="bank_transfer_instructions" rows="5"><?= kd_e($settings['bank_transfer_instructions']??'') ?></textarea></label><button class="btn secondary">Manuel ödeme ayarlarını kaydet</button></form></section></div>
<section class="panel customer-list-panel"><div class="panel-head"><h3>Ödeme hareketleri</h3><span class="result-count"><?= count($transactions) ?> kayıt</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Tarih</th><th>Sipariş</th><th>Sağlayıcı</th><th>Referans</th><th>Tutar</th><th>Durum</th><th>İşlem</th></tr></thead><tbody><?php foreach($transactions as $t): ?><tr><td><?= kd_e(date('d.m.Y H:i',strtotime($t['created_at']))) ?></td><td><?= kd_e($t['order_number']) ?></td><td><?= kd_e($t['provider']) ?></td><td><?= kd_e($t['provider_reference']) ?></td><td><?= number_format((float)$t['amount'],2,',','.') ?> <?= kd_e($t['currency']) ?></td><td><?= kd_e($t['status']) ?></td><td><?php if(in_array($t['provider'],['bank_transfer','cash_on_delivery'],true)&&$t['status']==='pending'): ?><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="manual_status"><input type="hidden" name="transaction_id" value="<?= (int)$t['id'] ?>"><button class="btn secondary" name="status" value="paid">Ödendi</button><button class="btn secondary" name="status" value="failed">Reddet</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$transactions): ?><tr><td colspan="6">Ödeme hareketi yok.</td></tr><?php endif; ?></tbody></table></div></section>
